package com.kynsoft.report.infrastructure.services;
import com.itextpdf.kernel.font.*; import com.itextpdf.kernel.pdf.*; import com.itextpdf.layout.*; import com.itextpdf.layout.element.*; import com.itextpdf.layout.properties.*; import com.kynsoft.report.domain.dto.DocumentoCajaResponse; import org.springframework.stereotype.Service; import java.io.ByteArrayOutputStream; import java.time.format.DateTimeFormatter; import java.util.UUID;
@Service public class DocumentoCajaPdfService {
 private final DocumentoCajaControlService documentos; public DocumentoCajaPdfService(DocumentoCajaControlService documentos){this.documentos=documentos;}
 public byte[] generar(UUID id){DocumentoCajaResponse d=documentos.obtener(id);try(ByteArrayOutputStream out=new ByteArrayOutputStream()){Document pdf=new Document(new PdfDocument(new PdfWriter(out)));PdfFont bold=PdfFontFactory.createFont("Helvetica-Bold"),normal=PdfFontFactory.createFont("Helvetica");pdf.add(new Paragraph(titulo(d)).setFont(bold).setFontSize(15).setTextAlignment(TextAlignment.CENTER));pdf.add(new Paragraph("No. "+d.getNumero()+"  |  Estado: "+d.getEstado()).setFont(normal).setTextAlignment(TextAlignment.CENTER));Table t=new Table(new float[]{1,2}).useAllAvailableWidth().setMarginTop(18);fila(t,"Fecha",d.getFecha().format(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm")),bold,normal);fila(t,"Beneficiario",d.getBeneficiario(),bold,normal);fila(t,"Importe",String.format("%,.2f CUP",d.getImporte()),bold,normal);fila(t,"Concepto",d.getConcepto(),bold,normal);fila(t,"Referencia",s(d.getReferencia()),bold,normal);fila(t,"Entregado por",s(d.getEntregadoPor()),bold,normal);fila(t,"Recibido por",s(d.getRecibidoPor()),bold,normal);fila(t,"Autorizado por",s(d.getAutorizadoPor()),bold,normal);fila(t,"Observaciones",s(d.getObservaciones()),bold,normal);pdf.add(t);pdf.add(new Paragraph("\n\n____________________________       ____________________________       ____________________________\nEntregado por                              Recibido por                              Autorizado por").setFont(normal).setFontSize(9).setTextAlignment(TextAlignment.CENTER));pdf.close();return out.toByteArray();}catch(Exception e){throw new IllegalStateException("No se pudo generar el documento de caja en PDF.",e);}}
 private String titulo(DocumentoCajaResponse d){return switch(d.getTipo()){case RECIBO_EFECTIVO->"RECIBO DE EFECTIVO";case VALE_PAGO_MENOR->"VALE PARA PAGOS MENORES";case ANTICIPO->"ANTICIPO DE EFECTIVO";case LIQUIDACION_ANTICIPO->"LIQUIDACIÓN DE ANTICIPO";case REEMBOLSO->"REEMBOLSO DE EFECTIVO";};} private String s(String s){return s==null||s.isBlank()?"-":s;}private void fila(Table t,String a,String b,PdfFont bold,PdfFont normal){t.addCell(new Cell().add(new Paragraph(a).setFont(bold).setFontSize(9)));t.addCell(new Cell().add(new Paragraph(b).setFont(normal).setFontSize(9)));}
}
